def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and
                            (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        stack.append((nx, ny))

            r0 = min(x for x, _ in comp)
            r1 = max(x for x, _ in comp)
            c0 = min(y for _, y in comp)
            c1 = max(y for _, y in comp)
            rh, cw = r1 - r0 + 1, c1 - c0 + 1

            perimeter = {
                (x, y)
                for x in range(r0, r1 + 1)
                for y in range(c0, c1 + 1)
                if x in (r0, r1) or y in (c0, c1)
            }
            if set(comp) != perimeter or rh < 3 or cw < 3:
                continue

            fill = 7 if rh == 3 and cw == 3 else 2
            for x in range(r0 + 1, r1):
                for y in range(c0 + 1, c1):
                    if grid[x][y] == bg:
                        out[x][y] = fill

    return out
